<template>
  <div class="identity-desk"><section class="identity-desk-intro"><span>TRUST & COMMUNITY</span><h2>核对组织关系，处理具体冒用。</h2><p>名称允许重复。每次决定需说明事实与影响范围，成员、会费和团内资料不随申诉移交。</p></section>
    <div class="identity-desk-tabs" role="tablist" aria-label="跑团身份工单"><button type="button" role="tab" :aria-selected="kind === 'verification'" :class="{ on: kind === 'verification' }" @click="pick('verification')">组织身份核验</button><button type="button" role="tab" :aria-selected="kind === 'report'" :class="{ on: kind === 'report' }" @click="pick('report')">名称与身份申诉</button></div>
    <p v-if="error" class="identity-desk-error" role="alert">{{ error }}<button v-if="!saving" type="button" @click="load">重新加载</button></p><p v-if="notice" class="identity-desk-notice" role="status">{{ notice }}</p>
    <div class="identity-desk-grid"><section class="identity-desk-list"><p v-if="loading" class="identity-desk-empty" role="status">正在读取私密工单…</p><p v-else-if="!rows.length" class="identity-desk-empty">暂时没有{{ kind === 'verification' ? '核验申请' : '身份申诉' }}。</p><button v-for="row in rows" :key="row.id" type="button" class="identity-case" :class="{ selected: selected?.id === row.id }" @click="open(row)"><div><span>{{ (kind === "report" ? reportStatuses[row.status] : identityStatuses[row.status]) || row.status }}</span><small>#{{ row.id }}</small></div><h3>{{ row.clubName }}</h3><p>{{ row.city || '城市待补充' }} · 团号 #{{ row.clubId }}</p><p>{{ kind === 'verification' ? '申请人 ' + (row.ownerNickname || row.owner || '—') : (reportTypes[row.type] || row.type) + ' · ' + (row.reporterNickname || row.reporter || '—') }}</p><small>{{ identityDate(row.createdAt) }}</small></button><div v-if="pages > 1" class="identity-pager"><button type="button" :disabled="loading || saving || page <= 1" @click="changePage(-1)">上一页</button><span>{{ page }}/{{ pages }} · {{ total }} 条</span><button type="button" :disabled="loading || saving || page >= pages" @click="changePage(1)">下一页</button></div></section>
      <section v-if="selected" class="identity-case-detail"><header><span>私密材料 · 仅平台管理员</span><h2>{{ selected.clubName }} · #{{ selected.clubId }}</h2><p>{{ kind === 'verification' ? '组织管理授权核验' : reportTypes[selected.type] }} · 工单 #{{ selected.id }}</p></header><dl v-if="kind === 'verification'"><dt>组织名称</dt><dd>{{ selected.organization }}</dd><dt>授权范围</dt><dd>{{ selected.scope }}</dd><dt>管理关系材料</dt><dd>{{ selected.evidence }}</dd></dl><dl v-else><dt>事实与说明</dt><dd>{{ selected.detail }}</dd></dl><dl><dt>联系方式</dt><dd>{{ selected.contact || '未填写' }}</dd><dt>公共来源</dt><dd><a v-if="safeSource(selected.sourceUrl)" :href="safeSource(selected.sourceUrl)" target="_blank" rel="noopener noreferrer">{{ selected.sourceUrl }} ↗</a><template v-else>{{ selected.sourceUrl || '未填写' }}</template></dd></dl><p class="identity-desk-hint">外部链接由处理人员按需查看，平台不会自动抓取。请在回复中使用脱敏事实摘要，勿泄露联系人或私密材料。</p><div v-if="selected.note" class="identity-existing-note"><b>最近回复</b><p>{{ selected.note }}</p></div>
        <form @submit.prevent="save"><h3>处理决定</h3><label>下一步<select v-model="decision" aria-label="下一步" :disabled="saving"><option v-for="item in decisions" :key="item[0]" :value="item[0]">{{ item[1] }}</option></select></label><label v-if="decision === 'rename'">更正后的名称<input v-model="nextName" required maxlength="20" :disabled="saving" placeholder="不更换团号，不转移团内资料" /></label><label>处理依据与下一步说明<textarea v-model="note" aria-label="处理依据与下一步说明" required maxlength="1000" rows="5" :disabled="saving" placeholder="说明已核对的事实、影响范围、需要补充的材料和复核方式。此回复会向有关用户展示，请勿写入私密联系方式。" /></label><p v-if="['restrict', 'rename', 'revoke'].includes(decision)" class="identity-desk-warning">{{ decision === 'restrict' ? '将限制该跑团的公开搜索与新招募。团内成员和历史记录继续保留。' : decision === 'rename' ? '将更正公开团名并暂停原核验标记。公开团号、成员与历史资料保留。' : '将停止展示核验标记，保留决定记录与基础功能。' }}</p><button class="identity-decision-submit" type="submit" :disabled="saving">{{ saving ? '正在保存…' : '确认并记录决定' }}</button></form>
        <section v-if="selected.events?.length" class="identity-events"><h3>处理记录</h3><article v-for="(event, index) in selected.events" :key="index"><span>{{ identityDate(event.createdAt) }} · {{ event.actor }} · {{ event.decision }}</span><p>{{ event.note }}</p></article></section>
      </section><section v-else class="identity-case-detail identity-desk-empty">选择一条工单，核对资料后再决定。</section>
    </div>
  </div>
</template>
<script setup>
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import { identityDate, identityStatuses, reportStatuses, reportTypes, safeSource } from '../../club-identity';
const props = defineProps({ request: { type: Function, required: true }, refreshKey: Number, sessionToken: String });
const kind = ref('verification'), rows = ref([]), selected = ref(null), page = ref(1), pages = ref(1), total = ref(0), loading = ref(false), saving = ref(false), error = ref(''), notice = ref(''), decision = ref('supplement'), note = ref(''), nextName = ref('');
let version = 0, disposed = false;
const decisions = computed(() => kind.value === 'verification' ? [['supplement','请申请人补充材料'],['approve','通过组织管理关系核验'],['reject','本次核验未通过'],['revoke','撤销原有核验标记']] : [['supplement','请补充事实与材料'],['restrict','限制公开搜索与新招募'],['restore','恢复公开展示'],['rename','更正误导性的团名'],['dismiss','结案，保留合理同名']]);
function clearPrivate() { version++; rows.value = []; selected.value = null; note.value = ''; nextName.value = ''; error.value = ''; notice.value = ''; loading.value = false; saving.value = false; }
function current(stamp) { if (props.sessionToken !== sessionStorage.getItem('marathon_admin')) { clearPrivate(); return false; } return !disposed && stamp.token === props.sessionToken && stamp.version === version; }
function stamp() { return { version, token: props.sessionToken }; }
async function load() { const state = { ...stamp(), version: ++version }; if (!current(state)) return; loading.value = true; error.value = ''; try { const data = await props.request('/admin/club-identity?' + new URLSearchParams({ kind: kind.value, page: String(page.value) })); if (!current(state)) return; rows.value = data.rows || []; pages.value = data.pages || 1; page.value = data.page || 1; total.value = data.total || 0; if (selected.value) selected.value = rows.value.find(row => row.id === selected.value.id) || null; } catch (err) { if (current(state)) error.value = err.message; } finally { if (current(state)) loading.value = false; } }
function open(row) { if (saving.value) return; selected.value = row; decision.value = 'supplement'; note.value = ''; nextName.value = row.clubName; notice.value = ''; }
function pick(value) { if (saving.value || value === kind.value) return; kind.value = value; selected.value = null; note.value = ''; nextName.value = ''; notice.value = ''; page.value = 1; load(); }
function changePage(delta) { page.value += delta; selected.value = null; load(); }
async function save() { if (saving.value || !selected.value) return; const state = stamp(); if (!current(state)) return; if (note.value.trim().length < 2) { error.value = '请填写可供用户理解与复核的处理依据。'; return; } const targetKind = kind.value, id = selected.value.id; saving.value = true; error.value = ''; notice.value = ''; try { await props.request('/admin/club-identity/' + targetKind + '/' + id + '/decision', { method: 'POST', body: JSON.stringify({ decision: decision.value, note: note.value.trim(), ...(decision.value === 'rename' ? { name: nextName.value.trim() } : {}) }) }); if (!current(state)) return; note.value = ''; saving.value = false; notice.value = '处理决定已记录，相关用户可查看回复并补充说明。'; await load(); } catch (err) { if (current(state)) error.value = err.message; } finally { if (!disposed && state.token === props.sessionToken) saving.value = false; } }
function checkSession() { if (props.sessionToken !== sessionStorage.getItem('marathon_admin')) clearPrivate(); }
window.addEventListener('storage', checkSession); window.addEventListener('focus', checkSession);
watch(() => props.refreshKey, () => { if (!saving.value) load(); });
watch(() => props.sessionToken, () => { clearPrivate(); if (props.sessionToken) load(); });
onBeforeUnmount(() => { disposed = true; clearPrivate(); window.removeEventListener('storage', checkSession); window.removeEventListener('focus', checkSession); }); load();
</script>
