il dd{margin:0;white-space:pre-wrap;color:#596474}.identity-case-detail a{color:#a5677c;text-decoration:underline}.identity-desk-hint{font-size:11px;color:#99a2af;line-height:1.9}.identity-existing-note{padding:15px;border-radius:10px;background:#fff9fb;font-size:12px;color:#987782;line-height:1.9}.identity-existing-note p{white-space:pre-wrap;margin:6px 0 0}.identity-case-detail form{margin-top:25px;padding-top:20px;border-top:1px solid #eceff3}.identity-case-detail h3{font-size:16px;margin:0 0 18px}.identity-case-detail label{display:grid;gap:9px;font-size:12px;color:#697587;margin-bottom:17px}.identity-case-detail input,.identity-case-detail select,.identity-case-detail textarea{width:100%;min-width:0;min-height:46px;padding:11px 12px;border:1px solid #e2e7ed;border-radius:9px;background:#fbfcfd;font:inherit;line-height:1.8}.identity-decision-submit{padding:10px 18px;background:#f22550;color:white;border-radius:9px;font-weight:600;font-size:13px}.identity-desk-error,.identity-desk-notice{padding:14px 17px;border-radius:10px;background:#fff1f5;color:#b54663;line-height:1.8;font-size:13px}.identity-desk-error button{color:#b54663;margin-left:10px}.identity-desk-notice{background:#eef8f2;color:#4d8269}.identity-desk-warning{padding:13px;border-radius:9px;background:#fff6ed;color:#a67b55;font-size:12px;line-height:1.9}.identity-desk-empty{padding:40px 20px;color:#99a3b2;font-size:12px;text-align:center;line-height:1.9}.identity-pager{display:flex;align-items:center;justify-content:center;gap:10px;padding:10px;font-size:11px;color:#9ca6b4}.identity-pager button{font-size:11px;color:#8c7985}.identity-events{margin-top:24px;padding-top:22px;border-top:1px solid #eceff3}.identity-events article{padding-left:12px;border-left:2px solid #f4e4eb}.identity-events article span{font-size:10px;color:#a0a8b4}.identity-events article p{font-size:12px;line-height:1.9;white-space:pre-wrap;color:#8390a1}.identity-desk button:disabled{opacity:.45}.identity-desk button:focus-visible,.identity-desk input:focus-visible,.identity-desk select:focus-visible,.identity-desk textarea:focus-visible{outline:2px solid #f15a7c;outline-offset:3px}@media(max-width:850px){.identity-desk-grid{grid-template-columns:minmax(0,1fr)}.identity-desk-intro{padding:20px}.identity-desk-intro h2{font-size:21px}.identity-case-detail{padding:20px}.identity-case-detail dl{grid-template-columns:65px minmax(0,1fr);padding:13px}}
